//! The registry's container: kept running with the server's configuration, stopped for garbage collection, and
//! started again.
//!
//! ```text
//! STATE/registry/config.yml   the registry's configuration, generated by the server
//! STATE/registry/secret       the secret it signs upload state with, made once
//! STATE/registry/data/        its storage, mounted at /var/lib/registry
//! ```
//!
//! The container runs as the server's own user, so the server owns its storage. It's published only on loopback
//! (`listen`), where the ingress reaches it; it checks no credentials itself, since the ingress has the server check
//! every request first.

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use anyhow::{Context, bail};
use futures_util::future::BoxFuture;
use sha2::{Digest, Sha256};
use tokio::process::Command;

use super::RegistryConfig;

/// The label holding a hash of how the container was made, so a change of image, port or configuration replaces it.
const SPEC_LABEL: &str = "kiwi-nest.registry-spec";

/// Where the registry reads its configuration, in the container.
pub const CONFIG_IN_CONTAINER: &str = "/etc/distribution/config.yml";

/// What the server needs from the registry's container.
pub trait Container: Send + Sync + 'static {
    /// Makes sure it's running as configured (creating or replacing it if needed), and answering.
    fn ensure(&self) -> BoxFuture<'_, anyhow::Result<()>>;
    /// Stops it, for garbage collection.
    fn stop(&self) -> BoxFuture<'_, anyhow::Result<()>>;
    /// Runs the registry's offline garbage collection on its storage, while it's stopped; returns its output.
    /// `delete_untagged` also removes manifests no tag names.
    fn collect(&self, delete_untagged: bool) -> BoxFuture<'_, anyhow::Result<String>>;
}

/// The registry's configuration file.
pub fn config_file(secret: &str) -> String {
    format!(
        r#"# Written by kiwi-nest; changes are overwritten.
version: 0.1
log:
  level: info
  fields:
    service: registry
storage:
  filesystem:
    rootdirectory: /var/lib/registry
  delete:
    enabled: true
  maintenance:
    uploadpurging:
      enabled: true
      age: 168h
      interval: 24h
      dryrun: false
http:
  addr: :5000
  secret: {secret}
  relativeurls: true
  headers:
    X-Content-Type-Options: [nosniff]
health:
  storagedriver:
    enabled: true
    interval: 10s
    threshold: 3
"#
    )
}

/// The registry in Docker.
pub struct Docker {
    cfg: RegistryConfig,
    dir: PathBuf,
    user: String,
}

/// Reads the secret, making it the first time.
fn secret(path: &Path) -> anyhow::Result<String> {
    match std::fs::read_to_string(path) {
        Ok(s) if !s.trim().is_empty() => return Ok(s.trim().to_string()),
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(e) => return Err(e).with_context(|| format!("reading {}", path.display())),
    }
    let mut bytes = [0u8; 32];
    getrandom::fill(&mut bytes).expect("the system's random number generator");
    let s = hex::encode(bytes);
    write_private(path, s.as_bytes())?;
    Ok(s)
}

/// Writes a file only its owner can read, atomically.
fn write_private(path: &Path, bytes: &[u8]) -> anyhow::Result<()> {
    let dir = path.parent().unwrap_or(Path::new("."));
    let mut tmp = tempfile::NamedTempFile::new_in(dir)?;
    std::io::Write::write_all(&mut tmp, bytes)?;
    tmp.as_file().sync_all()?;
    tmp.persist(path)?;
    Ok(())
}

impl Docker {
    /// Prepares the registry's files under `STATE/registry`.
    pub fn new(cfg: RegistryConfig, state_dir: &Path) -> anyhow::Result<Docker> {
        let dir = state_dir.join("registry");
        let text = dir.to_str().context("the state directory must be a UTF-8 path")?;
        if text.contains([',', ':', '"']) {
            bail!("the registry's directory can't contain `,`, `:` or `\"`: {text}");
        }
        std::fs::create_dir_all(dir.join("data")).with_context(|| format!("creating {}", dir.display()))?;
        // SAFETY: getuid and getgid can't fail.
        let (uid, gid) = unsafe { (libc::getuid(), libc::getgid()) };
        Ok(Docker {
            cfg,
            dir,
            user: format!("{uid}:{gid}"),
        })
    }

    fn command(&self) -> Command {
        let mut c = Command::new(&self.cfg.docker);
        c.stdin(std::process::Stdio::null()).kill_on_drop(true);
        c
    }

    async fn run(&self, mut c: Command) -> anyhow::Result<String> {
        let what = format!("{:?}", c.as_std());
        let out = c
            .output()
            .await
            .with_context(|| format!("running {}", self.cfg.docker.display()))?;
        if !out.status.success() {
            bail!(
                "{what} failed ({}): {}",
                out.status,
                String::from_utf8_lossy(&out.stderr).trim()
            );
        }
        Ok(String::from_utf8_lossy(&out.stdout).into_owned())
    }

    fn config_path(&self) -> PathBuf {
        self.dir.join("config.yml")
    }

    /// Writes the configuration, if it's changed; returns its contents.
    fn write_config(&self) -> anyhow::Result<String> {
        let secret = secret(&self.dir.join("secret"))?;
        let text = config_file(&secret);
        if std::fs::read_to_string(self.config_path()).ok().as_deref() != Some(text.as_str()) {
            write_private(&self.config_path(), text.as_bytes())?;
        }
        Ok(text)
    }

    /// The mounts and user that the registry and its garbage collection run with.
    fn mounts(&self, c: &mut Command) {
        c.args(["--user", &self.user])
            .arg("--mount")
            .arg(format!(
                "type=bind,src={},dst=/var/lib/registry",
                self.dir.join("data").display()
            ))
            .arg("--mount")
            .arg(format!(
                "type=bind,src={},dst={CONFIG_IN_CONTAINER},readonly",
                self.config_path().display()
            ));
    }

    /// A hash of everything the container is made from.
    fn spec(&self, config: &str) -> String {
        let mut h = Sha256::new();
        for part in [
            self.cfg.image.as_str(),
            &self.cfg.listen.to_string(),
            &self.user,
            &self.dir.display().to_string(),
            config,
        ] {
            h.update(part.as_bytes());
            h.update([0]);
        }
        hex::encode(h.finalize())[..16].to_string()
    }

    /// The container's spec label and whether it's running, or `None` if there's no such container.
    async fn current(&self) -> anyhow::Result<Option<(String, bool)>> {
        let mut c = self.command();
        c.args([
            "container",
            "inspect",
            "--format",
            &format!("{{{{index .Config.Labels \"{SPEC_LABEL}\"}}}}|{{{{.State.Running}}}}"),
            &self.cfg.container,
        ]);
        let out = c.output().await.context("running docker")?;
        if !out.status.success() {
            let err = String::from_utf8_lossy(&out.stderr);
            if err.contains("No such") || err.contains("no such") {
                return Ok(None);
            }
            bail!("docker container inspect failed: {}", err.trim());
        }
        let text = String::from_utf8_lossy(&out.stdout);
        let (spec, running) = text.trim().split_once('|').unwrap_or(("", "false"));
        Ok(Some((spec.to_string(), running == "true")))
    }

    async fn create(&self, spec: &str) -> anyhow::Result<()> {
        let mut c = self.command();
        c.args(["run", "--detach", "--name", &self.cfg.container])
            .args(["--restart", "unless-stopped"])
            .args(["--label", &format!("{SPEC_LABEL}={spec}")])
            .args(["--publish", &format!("{}:5000", self.cfg.listen)]);
        self.mounts(&mut c);
        c.arg(&self.cfg.image);
        self.run(c).await?;
        tracing::info!(container = self.cfg.container, image = self.cfg.image, listen = %self.cfg.listen, "started the registry");
        Ok(())
    }

    async fn wait_ready(&self) -> anyhow::Result<()> {
        let client = super::client::Client::new(self.cfg.listen)?;
        let deadline = Instant::now() + Duration::from_secs(60);
        while !client.ping().await {
            if Instant::now() > deadline {
                bail!("the registry at {} didn't answer within a minute", self.cfg.listen);
            }
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
        Ok(())
    }
}

impl Container for Docker {
    fn ensure(&self) -> BoxFuture<'_, anyhow::Result<()>> {
        Box::pin(async move {
            // Two small files.
            let config = self.write_config()?;
            let spec = self.spec(&config);
            match self.current().await? {
                Some((s, true)) if s == spec => {}
                Some((s, false)) if s == spec => {
                    let mut c = self.command();
                    c.args(["container", "start", &self.cfg.container]);
                    self.run(c).await?;
                    tracing::info!(container = self.cfg.container, "started the registry again");
                }
                Some(_) => {
                    let mut c = self.command();
                    c.args(["container", "rm", "--force", &self.cfg.container]);
                    self.run(c).await?;
                    tracing::info!(container = self.cfg.container, "replacing the registry's container");
                    self.create(&spec).await?;
                }
                None => self.create(&spec).await?,
            }
            self.wait_ready().await
        })
    }

    fn stop(&self) -> BoxFuture<'_, anyhow::Result<()>> {
        Box::pin(async move {
            let mut c = self.command();
            c.args(["container", "stop", "--time", "30", &self.cfg.container]);
            self.run(c).await.map(drop)
        })
    }

    fn collect(&self, delete_untagged: bool) -> BoxFuture<'_, anyhow::Result<String>> {
        Box::pin(async move {
            let mut c = self.command();
            c.args(["run", "--rm"]);
            self.mounts(&mut c);
            c.arg(&self.cfg.image).arg("garbage-collect");
            if delete_untagged {
                c.arg("--delete-untagged");
            }
            c.arg(CONFIG_IN_CONTAINER);
            self.run(c).await
        })
    }
}
